function joinWords(words) {
  const parts = [];
  for (let i = 0; i < words.length; i++) {
    if (i > 0) parts.push(" ");
    parts.push(words[i]);                   // O(1): just remember the piece
  }
  return parts.join("");                    // one pass copies each character once
}

def join_words(words):
    parts = []
    for i, word in enumerate(words):
        if i > 0:
            parts.append(" ")
        parts.append(word)                # O(1): just remember the piece
    return "".join(parts)                 # one pass copies each character once

String joinWords(String[] words) {
    StringBuilder sb = new StringBuilder();      // a growable buffer of characters
    for (int i = 0; i < words.length; i++) {
        if (i > 0) sb.append(' ');
        sb.append(words[i]);                     // amortized O(1) per character, like an ArrayList
    }
    return sb.toString();                        // one final copy into an immutable String
}

string joinWords(const vector<string>& words) {
    string s;
    for (size_t i = 0; i < words.size(); i++) {
        if (i > 0) s += ' ';
        s += words[i];                           // appends in place: amortized O(1) per character
    }
    return s;
}
